const reply=(value,status=200)=>Response.json(value,{status,headers:{"Cache-Control":"no-store"}});
const secret=()=>crypto.randomUUID().replaceAll("-","");
export async function api(request,db){
  if(request.method!=="POST" || (request.headers.get("Origin") && request.headers.get("Origin")!==new URL(request.url).origin))return reply({error:"Richiesta non valida."},403);
  const path=new URL(request.url).pathname.slice(5), raw=await request.text();
  if(raw.length>24000)return reply({error:"Richiesta troppo lunga."},413);
  const data=JSON.parse(raw), now=Date.now();
  if(path==="create"){
    const id=secret(),host=secret(), room={host,slots:[null,null,null,null],snapshot:data.snapshot,queue:[],last:0};
    await db.batch([db.prepare("DELETE FROM rooms WHERE expires < ?").bind(now),db.prepare("INSERT INTO rooms VALUES(?,0,?,?)").bind(id,now+7200000,JSON.stringify(room))]);
    return reply({id,host});
  }
  for(let attempt=0;attempt<6;attempt++){
    const row=await db.prepare("SELECT version,data FROM rooms WHERE id=? AND expires>?").bind(data.id||"",now).first();
    if(!row)return reply({error:"Stanza scaduta. Chiedi il nuovo link."},404);
    const r=JSON.parse(row.data), user=r.slots.indexOf(data.token), host=data.token===r.host, seats=r.slots.map(Boolean);
    let result={};
    if(path==="view")return reply({snapshot:r.snapshot,seats,now,user});
    if(path==="poll"&&host)return reply({commands:r.queue,seats});
    if(path==="join"){
      if(!Number.isInteger(data.seat)||data.seat<0||data.seat>3)return reply({error:"Posto non valido."},400);
      if(user>=0)return reply({seat:user,token:data.token});
      if(seats[data.seat])return reply({error:"Nome già scelto."},409);
      if(!/^[a-f0-9]{32}$/.test(data.token||""))return reply({error:"Riprova dal telefono."},400);
      r.slots[data.seat]=data.token;result={seat:data.seat,token:data.token};
    }else if(path==="sync"&&host){
      if(data.snapshot.epoch>=r.snapshot.epoch)r.snapshot=data.snapshot;
      r.queue=r.queue.filter(c=>c.seq>data.ack && c.epoch===r.snapshot.epoch);
    }else if(path==="play" && user>=0){
      const s=r.snapshot, isChallenge=["duel","group"].includes(s.phase), allowed=s.actor===user||s.challenge.includes(user);
      if(!allowed || data.epoch!==s.epoch || (s.phaseDeadline&&now>s.phaseDeadline))return reply({error:"Turno concluso."},409);
      const reveal=data.kind==="reveal"&&s.phase==="armed";
      if(!reveal && !(["question","gate","gold","bonus","group","duel"].includes(s.phase)&&Number.isInteger(data.choice)&&s.question.options[data.choice]!==undefined))return reply({error:"Scelta non valida."},400);
      const kind=reveal?"reveal":isChallenge?"challenge":"answer";
      if(!r.queue.some(c=>c.epoch===s.epoch && c.team===user && c.kind===kind)){
        r.queue.push({seq:++r.last,team:user,epoch:s.epoch,kind,value:isChallenge?s.question.options[data.choice]:data.choice});
      }
    }else return reply({error:"Accesso non valido."},403);
    const out=await db.prepare("UPDATE rooms SET version=version+1,data=? WHERE id=? AND version=?").bind(JSON.stringify(r),data.id,row.version).run();
    if(out.meta.changes)return reply(result);
  }
  return reply({error:"Stanza occupata, riprova."},409);
}

const assets={"/": ["text/html", ""], "/scene.js": ["text/javascript", ""], "/quiz.js": ["text/javascript", ""], "/room.js": ["text/javascript", ""], "/engine.js": ["text/javascript", ""], "/game.css": ["text/css", ""], "/game.js": ["text/javascript", ""], "/island.webp": ["image/webp", ""], "/qr.js": ["text/javascript", ""]};
export default {async fetch(request,env){
 const url=new URL(request.url);
 if(url.pathname.startsWith("/api/")){try{return await api(request,env.DB);}catch(e){console.error(e.message);return reply({error:"Stanza temporaneamente indisponibile."},503);}}
 const asset=assets[url.pathname==="/index.html"?"/":url.pathname];if(!Array.isArray(asset))return new Response("Pagina non trovata",{status:404});
 return new Response(Uint8Array.from(atob(asset[1]),c=>c.charCodeAt(0)),{headers:{"Content-Type":asset[0],"Cache-Control":"no-cache"}});
}};